<div class="row g-4"><div class="col-xl-8">
<div class="card mb-4"><div class="card-header d-flex justify-content-between"><strong>Itens</strong><span class="badge text-bg-<?=$open?'warning':'success'?>"><?=htmlspecialchars($command['status'])?></span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Item</th><th>Profissional</th><th>Qtd.</th><th>Unit.</th><th>Desconto</th><th>Total</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?=htmlspecialchars($i['description'])?></strong><small class="d-block text-secondary"><?=htmlspecialchars($i['item_type'])?><?=$i['covered_by_package']?' · coberto por pacote':''?><?=$i['is_primary_service']?' · serviço principal':''?></small></td><td><?=htmlspecialchars($i['professional_name']??'—')?></td><td><?=number_format((float)$i['quantity'],3,',','.')?></td><td>R$ <?=number_format((float)$i['unit_price'],2,',','.')?></td><td>R$ <?=number_format((float)$i['discount_amount'],2,',','.')?></td><td><strong>R$ <?=number_format((float)$i['total_amount'],2,',','.')?></strong></td><td><?php if($open&&!$i['is_primary_service']):?><form method="post" action="/barber/commands/<?=(int)$command['id']?>/items/<?=(int)$i['id']?>/remove" onsubmit="return confirm('Remover item?')"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Remover</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if($open):?><div class="card mb-4"><div class="card-body"><h2 class="h5">Adicionar item</h2><form method="post" action="/barber/commands/<?=(int)$command['id']?>/items" class="row g-3" data-command-item-form><?=\App\Core\CSRF::field()?><div class="col-md-3"><label class="form-label">Tipo</label><select class="form-select" name="item_type" data-item-type><option value="service">Serviço</option><option value="product">Produto</option><option value="manual">Item manual</option></select></div><div class="col-md-5" data-service-field><label class="form-label">Serviço</label><select class="form-select" name="service_id"><option value="">Selecione</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?> · R$ <?=number_format((float)$s['price'],2,',','.')?></option><?php endforeach;?></select></div><div class="col-md-5 d-none" data-product-field><label class="form-label">Produto</label><select class="form-select" name="product_id"><option value="">Selecione</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?> · R$ <?=number_format((float)$p['sale_price'],2,',','.')?> · estoque <?=number_format((float)$p['stock'],3,',','.')?></option><?php endforeach;?></select></div><div class="col-md-5 d-none" data-manual-field><label class="form-label">Descrição</label><input class="form-control" name="description" placeholder="Ex.: hidratação, taxa extra"></div><div class="col-md-2 d-none" data-manual-price><label class="form-label">Valor unitário</label><input class="form-control" type="number" step="0.01" min="0" name="unit_price"></div><div class="col-md-2"><label class="form-label">Qtd.</label><input class="form-control" type="number" step="0.001" min="0.001" name="quantity" value="1"></div><div class="col-md-2"><label class="form-label">Desconto</label><input class="form-control" type="number" step="0.01" min="0" name="discount_amount" value="0"></div><div class="col-md-4"><label class="form-label">Profissional</label><select class="form-select" name="professional_id"><option value="">Profissional principal</option><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>" <?=(int)($command['professional_id']??0)===(int)$p['id']?'selected':''?>><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary w-100">Adicionar</button></div></form></div></div><?php endif;?>
</div><div class="col-xl-4">
<div class="card mb-4"><div class="card-body"><h2 class="h5">Resumo</h2><div class="d-flex justify-content-between"><span>Itens</span><strong>R$ <?=number_format((float)$command['subtotal'],2,',','.')?></strong></div><div class="d-flex justify-content-between"><span>Desconto geral</span><strong>- R$ <?=number_format((float)$command['discount_amount'],2,',','.')?></strong></div><div class="d-flex justify-content-between"><span>Acréscimo</span><strong>R$ <?=number_format((float)$command['surcharge_amount'],2,',','.')?></strong></div><div class="d-flex justify-content-between"><span>Gorjeta</span><strong>R$ <?=number_format((float)$command['tip_amount'],2,',','.')?></strong></div><hr><div class="d-flex justify-content-between h5"><span>Total</span><strong>R$ <?=number_format((float)$command['total_amount'],2,',','.')?></strong></div><div class="d-flex justify-content-between text-success"><span>Recebido</span><strong>R$ <?=number_format($paid,2,',','.')?></strong></div><div class="d-flex justify-content-between <?=$remaining>0?'text-danger':'text-success'?>"><span>Saldo</span><strong>R$ <?=number_format($remaining,2,',','.')?></strong></div></div></div>
<?php if($open):?><div class="card mb-4"><div class="card-body"><h2 class="h5">Ajustes e gorjeta</h2><form method="post" action="/barber/commands/<?=(int)$command['id']?>/adjustments" class="row g-2"><?=\App\Core\CSRF::field()?><div class="col-6"><label class="form-label">Desconto</label><input class="form-control" type="number" step=".01" min="0" name="discount_amount" value="<?=htmlspecialchars((string)$command['discount_amount'])?>"></div><div class="col-6"><label class="form-label">Acréscimo</label><input class="form-control" type="number" step=".01" min="0" name="surcharge_amount" value="<?=htmlspecialchars((string)$command['surcharge_amount'])?>"></div><div class="col-6"><label class="form-label">Gorjeta</label><input class="form-control" type="number" step=".01" min="0" name="tip_amount" value="<?=htmlspecialchars((string)$command['tip_amount'])?>"></div><div class="col-6"><label class="form-label">Para</label><select class="form-select" name="tip_professional_id"><option value="">Selecione</option><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>" <?=(int)($command['tip_professional_id']??0)===(int)$p['id']?'selected':''?>><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-outline-primary w-100">Atualizar</button></div></form></div></div>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Receber</h2><form method="post" action="/barber/commands/<?=(int)$command['id']?>/payments" class="row g-2"><?=\App\Core\CSRF::field()?><div class="col-6"><label class="form-label">Forma</label><select class="form-select" name="method"><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="credito">Crédito</option><option value="debito">Débito</option><option value="outro">Outro</option></select></div><div class="col-6"><label class="form-label">Valor</label><input class="form-control" type="number" step=".01" min=".01" max="<?=htmlspecialchars((string)$remaining)?>" name="amount" value="<?=htmlspecialchars(number_format($remaining,2,'.',''))?>" required></div><div class="col-12"><button class="btn btn-success w-100" <?=$remaining<=0?'disabled':''?>>Registrar pagamento</button></div></form><?php if($payments):?><hr><small class="text-secondary">Pagamentos</small><?php foreach($payments as $p):?><div class="d-flex justify-content-between small mt-1"><span><?=htmlspecialchars(strtoupper($p['method']))?></span><strong>R$ <?=number_format((float)$p['amount'],2,',','.')?></strong></div><?php endforeach;?><?php endif;?></div></div>
<form method="post" action="/barber/commands/<?=(int)$command['id']?>/close" onsubmit="return confirm('Fechar esta comanda? Esta ação conclui o atendimento, baixa o estoque e gera financeiro/comissões.')"><?=\App\Core\CSRF::field()?><button class="btn btn-primary btn-lg w-100" <?=$remaining>0?'disabled':''?>>Fechar comanda</button></form><?php endif;?>
</div></div>
<script>(function(){var f=document.querySelector('[data-command-item-form]');if(!f)return;var t=f.querySelector('[data-item-type]'),s=f.querySelector('[data-service-field]'),p=f.querySelector('[data-product-field]'),m=f.querySelector('[data-manual-field]'),mp=f.querySelector('[data-manual-price]');function sync(){var v=t.value;s.classList.toggle('d-none',v!=='service');p.classList.toggle('d-none',v!=='product');m.classList.toggle('d-none',v!=='manual');mp.classList.toggle('d-none',v!=='manual');}t.addEventListener('change',sync);sync();})();</script>
